import React from "react";

const About = () => {
  return (
    <div className="container py-5">
      <h1 className="fw-bold text-danger">About Us</h1>
      <p className="lead">
        We connect donors with meaningful causes to help people
        and communities in need.
      </p>
    </div>
  );
};

export default About;
